SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000001',true);
DO $$ DECLARE rows jsonb; p uuid; task uuid:='70000000-0000-4000-8000-000000000005'; ctx uuid:='40000000-0000-4000-8000-000000000005'; org uuid:='20000000-0000-4000-8000-000000000001'; vals jsonb;req uuid:=gen_random_uuid(); BEGIN
 rows:=public.list_unified_tasks(org);
 PERFORM foundation_test.assert(EXISTS(SELECT 1 FROM jsonb_array_elements(rows) r WHERE r->>'id'=task::text AND r->>'project_id' IS NULL AND r->>'context_kind'='operational'),'unboarded operational task included without fake project');
 PERFORM foundation_test.assert(NOT EXISTS(SELECT 1 FROM jsonb_array_elements(rows) r WHERE r->>'organization_id'<>org::text),'unified read cannot leak other studios');
 PERFORM foundation_test.assert(jsonb_array_length(rows)=(SELECT count(DISTINCT r->>'id') FROM jsonb_array_elements(rows) r),'one record even with multiple assignees');
 SELECT id INTO p FROM public.projects WHERE work_context_id='40000000-0000-4000-8000-000000000002';
 PERFORM public.change_production_item(org,p,'archive_board','60000000-0000-4000-8000-000000000002',0,NULL,NULL,gen_random_uuid());
 rows:=public.list_unified_tasks(org);
 PERFORM foundation_test.assert(EXISTS(SELECT 1 FROM jsonb_array_elements(rows) r WHERE r->>'id'='70000000-0000-4000-8000-000000000002' AND (r->>'board_archived')::boolean),'assigned task stays visible when board archived');
 vals:=jsonb_build_object('title','Publish studio content','description','Editorial review','priority','high','due_date','2026-12-01','column_id',NULL,'category','in_progress','assignees',jsonb_build_array(auth.uid(),'10000000-0000-4000-8000-000000000005'));
 PERFORM public.save_operational_task(org,ctx,task,0,vals,req);
 PERFORM public.save_operational_task(org,ctx,task,0,vals,req);
 PERFORM foundation_test.assert((SELECT board_id IS NULL AND column_id IS NULL AND category='in_progress' AND revision=1 AND due_date='2026-12-01' FROM public.tasks WHERE id=task),'operational edit is canonical and date-only, no duplicate retry');
 PERFORM foundation_test.assert((SELECT count(*) FROM public.task_assignees WHERE task_id=task)=2,'operational assignments persist');
 PERFORM foundation_test.expect_error(format('SELECT public.save_operational_task(%L,%L,%L,0,%L,gen_random_uuid())',org,ctx,task,vals),'40001','stale operational edit denied');
 PERFORM foundation_test.expect_error(format('SELECT public.save_operational_task(%L,%L,%L,1,%L,gen_random_uuid())',org,ctx,task,vals||'{"assignees":["10000000-0000-4000-8000-000000000002"]}'),'42501','cross-studio operational assignment denied');
 PERFORM public.change_production_item(org,p,'archive_task','70000000-0000-4000-8000-000000000002',0,NULL,NULL,gen_random_uuid());
 PERFORM foundation_test.assert(NOT EXISTS(SELECT 1 FROM jsonb_array_elements(public.list_unified_tasks(org)) r WHERE r->>'id'='70000000-0000-4000-8000-000000000002'),'individually archived task excluded');
END $$;
SELECT set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000005',true);
SELECT foundation_test.assert(NOT EXISTS(SELECT 1 FROM jsonb_array_elements(public.list_unified_tasks('20000000-0000-4000-8000-000000000001')) r WHERE r->>'work_context_id' IN ('40000000-0000-4000-8000-000000000001','40000000-0000-4000-8000-000000000004')),'member sees only authorized work contexts');
RESET ROLE;
UPDATE public.work_context_memberships SET role='viewer' WHERE work_context_id='40000000-0000-4000-8000-000000000005' AND user_id='10000000-0000-4000-8000-000000000005';
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000005',true);
SELECT foundation_test.assert(EXISTS(SELECT 1 FROM jsonb_array_elements(public.list_unified_tasks('20000000-0000-4000-8000-000000000001')) r WHERE r->>'id'='70000000-0000-4000-8000-000000000005' AND NOT (r->>'can_write')::boolean),'viewer assignment is visible read-only');
SELECT foundation_test.expect_error($q$SELECT public.save_operational_task('20000000-0000-4000-8000-000000000001','40000000-0000-4000-8000-000000000005','70000000-0000-4000-8000-000000000005',1,'{}',gen_random_uuid())$q$,'42501','viewer cannot write operational tasks');
SELECT set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000007',true);
SELECT foundation_test.assert(public.list_unified_tasks('20000000-0000-4000-8000-000000000001')='[]'::jsonb,'client cannot query internal unified tasks');
RESET ROLE;
SELECT 'unified context/tenant isolation, archived-board visibility, operational edits, revisions and assignment checks passed' AS verification;
